using System.IO;using System.Text.Json;using System.Windows;using System.Windows.Automation;using System.Windows.Controls;using System.Windows.Media;using LifeOS.Core.ConfigurationReadiness;using LifeOS.Core.Forms;using LifeOS.Core.ProviderAdapters;using LifeOS.Shared.ProviderAdapters;using LifeOS.Shared.Storage;
namespace LifeOS.Desktop;
public sealed class ProviderAdapterWorkspaceView:UserControl
{
 private readonly bool _demo;private List<ProviderAdapterRecord>_records=[];private IReadOnlyList<FormFieldIssue>_issues=[];private UserFacingProblem?_problem;private string?_notice;private string _name="",_owner="",_reference="",_notes="";private ProviderFamily _family;private ConfigurationEnvironment _environment;private ProviderCapability _capabilities;
 public ProviderAdapterWorkspaceView(bool demo){_demo=demo;Background=B("#0C1220");Foreground=Brushes.White;FontFamily=new("Segoe UI");try{_records=ProviderAdapterStorage.Load();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or JsonException){_problem=UserFacingProblemFactory.FromException(ex,"load provider adapters");}Render();}
 private void Render(){StackPanel root=new(){Margin=new(24)};root.Children.Add(T(_demo?"PORTFOLIO DEMO • ISOLATED":"ORDINARY MODE • NO PROVIDERS ACTIVE",11,"#AFA4FF",FontWeights.SemiBold));root.Children.Add(T("Provider Adapter Registry & Capability Matrix",30,"#FFFFFF",FontWeights.Bold));root.Children.Add(T("Declare adapter ownership and capabilities without loading provider SDKs, credentials or endpoints. Provider writes remain disabled even when listed as a future capability.",14,"#B8C5D8"));if(_notice!=null)root.Children.Add(T(_notice,12,"#83D4B3",FontWeights.SemiBold));if(_problem!=null)root.Children.Add(Problem(_problem));WrapPanel m=new(){Margin=new(0,16,0,8)};m.Children.Add(Metric("Adapters",_records.Count.ToString(),"Metadata only"));m.Children.Add(Metric("Ready to test",_records.Count(x=>x.State==ProviderAdapterState.AvailableForCredentialedTest).ToString(),"No provider call"));m.Children.Add(Metric("Capabilities",_records.Sum(x=>Flags(x.Capabilities).Count()).ToString(),"Declared only"));m.Children.Add(Metric("Writes enabled","0","Hard boundary"));root.Children.Add(m);root.Children.Add(Capture());root.Children.Add(H("Capability matrix",21,new(0,20,0,6)));if(_records.Count==0)root.Children.Add(Card("No adapters registered","Ordinary mode starts empty. Add adapter metadata without credentials, endpoints or SDK loading.","#151F30"));else foreach(var r in _records)root.Children.Add(Record(r));LocalStoreHealth health=ProviderAdapterStorage.Inspect();root.Children.Add(H("Adapter boundary",21,new(0,20,0,6)));root.Children.Add(Card("Versioned provider-adapters store",$"State: {health.State}. This registry stores declarations only; it cannot instantiate an adapter or activate provider writes.","#152437"));Content=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Content=root};}
 private UIElement Capture(){StackPanel p=new();p.Children.Add(H("Register adapter metadata",20));WrapPanel row=new();row.Children.Add(Input("Adapter name *","adapter-name","ProviderAdapter.Name",_name,v=>_name=v,480));row.Children.Add(Input("Owner *","adapter-owner","ProviderAdapter.Owner",_owner,v=>_owner=v,480));p.Children.Add(row);WrapPanel choices=new();choices.Children.Add(Choice("Provider family","ProviderAdapter.Family",Enum.GetValues<ProviderFamily>(),_family,v=>_family=v,480));choices.Children.Add(Choice("Environment","ProviderAdapter.Environment",Enum.GetValues<ConfigurationEnvironment>(),_environment,v=>_environment=v,480));p.Children.Add(choices);p.Children.Add(H("Declared capabilities *",14,new(0,12,0,2)));WrapPanel caps=new();foreach(var x in Enum.GetValues<ProviderCapability>().Where(x=>x!=ProviderCapability.None)){ProviderCapability flag=x;CheckBox box=new(){Content=x.ToString(),Foreground=Brushes.White,Margin=new(0,4,18,4),IsChecked=_capabilities.HasFlag(x)};AutomationProperties.SetAutomationId(box,$"ProviderAdapter.Capability.{x}");box.Checked+=(_,_)=>_capabilities|=flag;box.Unchecked+=(_,_)=>_capabilities&=~flag;caps.Children.Add(box);}p.Children.Add(caps);string ce=string.Join(" ",_issues.Where(i=>i.FieldId=="adapter-capabilities").Select(i=>i.Message));if(ce.Length>0)p.Children.Add(T(ce,11,"#FF7788",FontWeights.SemiBold));p.Children.Add(Input("Credential reference name (optional)","adapter-credential-reference","ProviderAdapter.CredentialReference",_reference,v=>_reference=v,970));p.Children.Add(Input("Notes","adapter-notes","ProviderAdapter.Notes",_notes,v=>_notes=v,970));Button add=Btn("Add adapter declaration","ProviderAdapter.Add",false);add.Click+=(_,_)=>Add();p.Children.Add(add);return Panel(p,new(0,14,0,0));}
 private UIElement Record(ProviderAdapterRecord r){StackPanel p=new();DockPanel h=new();TextBlock s=T(Label(r.State),11,"#AFA4FF",FontWeights.SemiBold);DockPanel.SetDock(s,Dock.Right);h.Children.Add(s);h.Children.Add(H(r.Name,18));p.Children.Add(h);p.Children.Add(T($"{r.Family} • {r.Environment} • owner: {r.Owner}",12,"#A9B6CA"));p.Children.Add(T($"Capabilities: {string.Join(" • ",Flags(r.Capabilities))}",13,"#E7ECF4",FontWeights.SemiBold));p.Children.Add(T(r.CredentialReferenceName.Length==0?"Credential reference: not configured":$"Credential reference: {r.CredentialReferenceName} (name only)",12,"#C2CDDC"));p.Children.Add(T("Provider writes: DISABLED",12,"#FFB3BD",FontWeights.SemiBold));WrapPanel a=new();foreach(var x in new[]{ProviderAdapterState.Planned,ProviderAdapterState.Blocked,ProviderAdapterState.Retired}){ProviderAdapterState state=x;if(state==r.State)continue;Button b=Btn($"Mark {Label(state).ToLowerInvariant()}",$"ProviderAdapter.State.{state}.{r.Id:N}",true);b.Click+=(_,_)=>Change(r,state);a.Children.Add(b);}p.Children.Add(a);return Panel(p,new(0,8,0,0));}
 private void Add(){ProviderAdapterDraft d=new(_name,_family,_owner,_environment,_capabilities,_reference,_notes);FormValidationResult v=ProviderAdapterService.Validate(d);_issues=v.Issues;if(!v.IsValid){_problem=new("provider-adapter-validation-failed","Review the adapter fields","No adapter was added because the fields are invalid or appear to contain a credential.","Remove credential values and correct the highlighted fields.",true);Render();return;}try{var r=ProviderAdapterService.Create(d,DateTimeOffset.UtcNow);var c=_records.Append(r).ToList();ProviderAdapterStorage.Save(c);_records=c;_name=_owner=_reference=_notes="";_capabilities=ProviderCapability.None;_issues=[];_problem=null;_notice="Registered adapter metadata without loading a provider SDK.";Render();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or JsonException or InvalidDataException){_problem=UserFacingProblemFactory.FromException(ex,"save provider adapter");Render();}}
 private void Change(ProviderAdapterRecord r,ProviderAdapterState state){try{var x=ProviderAdapterService.SetState(r,state,DateTimeOffset.UtcNow);var c=_records.Select(v=>v.Id==r.Id?x:v).ToList();ProviderAdapterStorage.Save(c);_records=c;_notice=$"{r.Name} is now {Label(state).ToLowerInvariant()}.";_problem=null;Render();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or JsonException or InvalidDataException or InvalidOperationException){_problem=UserFacingProblemFactory.FromException(ex,"change provider adapter");Render();}}
 private UIElement Input(string l,string f,string id,string val,Action<string>ch,double w){StackPanel p=new(){Width=w,Margin=new(0,7,10,0)};p.Children.Add(T(l,12,"#C7D2E3",FontWeights.SemiBold));TextBox x=new(){Text=val,MinHeight=38,Background=B("#101827"),Foreground=Brushes.White,BorderBrush=B("#3A4B66"),Padding=new(10,7,10,7)};AutomationProperties.SetAutomationId(x,id);x.TextChanged+=(_,_)=>ch(x.Text);p.Children.Add(x);string e=string.Join(" ",_issues.Where(i=>i.FieldId==f).Select(i=>i.Message));if(e.Length>0)p.Children.Add(T(e,11,"#FF7788",FontWeights.SemiBold));return p;}private static UIElement Choice<TValue>(string l,string id,IReadOnlyList<TValue>vals,TValue sel,Action<TValue>ch,double w)where TValue:struct{StackPanel p=new(){Width=w,Margin=new(0,7,10,0)};p.Children.Add(T(l,12,"#C7D2E3",FontWeights.SemiBold));ComboBox x=new(){ItemsSource=vals,SelectedItem=sel,MinHeight=38};AutomationProperties.SetAutomationId(x,id);x.SelectionChanged+=(_,_)=>{if(x.SelectedItem is TValue v)ch(v);};p.Children.Add(x);return p;}private static List<string> Flags(ProviderCapability c)=>Enum.GetValues<ProviderCapability>().Where(x=>x!=ProviderCapability.None&&c.HasFlag(x)).Select(x=>x.ToString()).ToList();private static string Label(ProviderAdapterState s)=>s switch{ProviderAdapterState.AvailableForCredentialedTest=>"AVAILABLE FOR CREDENTIALED TEST",_=>s.ToString().ToUpperInvariant()};
 private static Border Problem(UserFacingProblem x){StackPanel p=new();p.Children.Add(H($"{x.Title} ({x.Code})",16));p.Children.Add(T(x.Detail,12,"#E1E7F0"));p.Children.Add(T($"Next: {x.RecoveryAction}",12,"#C5AECF"));return new(){Background=B("#251925"),BorderBrush=B("#C95F75"),BorderThickness=new(1),CornerRadius=new(9),Padding=new(15),Margin=new(0,12,0,0),Child=p};}private static Button Btn(string l,string id,bool s){Button b=new(){Content=l,Background=B(s?"#25334A":"#315E91"),Foreground=Brushes.White,Padding=new(14,7,14,7),Margin=new(0,8,8,0)};AutomationProperties.SetAutomationId(b,id);return b;}private static Border Metric(string l,string v,string d){StackPanel p=new();p.Children.Add(T(l,11,"#9EACC0"));p.Children.Add(T(v,22,"#FFFFFF",FontWeights.SemiBold));p.Children.Add(T(d,11,"#9EACC0"));return new(){Width=230,MinHeight=100,Background=B("#151F30"),BorderBrush=B("#31445F"),BorderThickness=new(1),CornerRadius=new(9),Padding=new(14),Margin=new(0,0,10,10),Child=p};}private static Border Card(string h,string t,string bg){StackPanel p=new();p.Children.Add(H(h,16));p.Children.Add(T(t,12,"#C2CDDC"));return new(){Background=B(bg),BorderBrush=B("#31445F"),BorderThickness=new(1),CornerRadius=new(9),Padding=new(16),Margin=new(0,8,0,0),Child=p};}private static Border Panel(UIElement x,Thickness m)=>new(){Background=B("#151F30"),BorderBrush=B("#31445F"),BorderThickness=new(1),CornerRadius=new(9),Padding=new(16),Margin=m,Child=x};private static TextBlock H(string t,double s,Thickness?m=null)=>new(){Text=t,FontSize=s,FontWeight=FontWeights.SemiBold,Foreground=Brushes.White,TextWrapping=TextWrapping.Wrap,Margin=m??new(0,0,0,4)};private static TextBlock T(string t,double s,string c,FontWeight?w=null)=>new(){Text=t,FontSize=s,FontWeight=w??FontWeights.Normal,Foreground=B(c),TextWrapping=TextWrapping.Wrap,Margin=new(0,3,0,0)};private static SolidColorBrush B(string v)=>new((Color)ColorConverter.ConvertFromString(v));
}
